document.addEventListener("DOMContentLoaded",init);const STATUS_OPTIONS=["Pending Payment","Paid","Fulfilled","Cancelled"];const ORDERS_PAGE_SIZE=20;let ownerOrders=[];let ordersHasMore=false;async function init(){const owner=await Auth.guardOwnerAuth();if(!owner)return;document.getElementById("store-name-label").textContent=shortStoreName(owner.storeName);document.getElementById("order-list").addEventListener("change",onStatusChange);document.getElementById("order-list").addEventListener("click",onSendInvoice);document.getElementById("orders-load-more").addEventListener("click",onLoadMore);await loadOrders()}async function loadOrders(opts){const limit=opts&&opts.limit||ownerOrders.length||ORDERS_PAGE_SIZE;const statusEl=document.getElementById("orders-status");const stopLoading=startLoadingMessage(statusEl);const res=await Api.post("listOwnerOrders",{token:Auth.getToken(),limit:limit});stopLoading();if(!res.ok){showLoadFailedMessage(statusEl);return}ownerOrders=res.orders;ordersHasMore=!!res.hasMore;statusEl.textContent=ownerOrders.length===0?"No orders yet.":`${ownerOrders.length} of ${res.total} order(s) shown.`;document.getElementById("orders-load-more").classList.toggle("hidden",!ordersHasMore);render()}function onLoadMore(){loadOrders({limit:ownerOrders.length+ORDERS_PAGE_SIZE})}function statusClass(status){return"status-"+status.toLowerCase().replace(/\s+/g,"-")}function roomLink(o){if(!o.room)return"";const href=`../order-room.html?order=${encodeURIComponent(o.orderId)}&as=seller`;const unread=o.room.unread>0?` <span class="order-room-badge" aria-label="${o.room.unread} new">${o.room.unread}</span>`:"";const stage=o.room.stage?`<span class="order-room-stage${o.room.dispute?" order-room-problem":""}">${escapeHtml(o.room.stage)}</span>`:"";return`<p><a class="btn btn-small order-room-link" href="${href}">Open order room${unread}</a>${stage}</p>`}function render(){const listEl=document.getElementById("order-list");listEl.innerHTML=ownerOrders.map(o=>{const options=STATUS_OPTIONS.map(s=>`<option value="${s}" ${s===o.status?"selected":""}>${s}</option>`).join("");const inRoom=o.room&&o.room.flow==="v1";return`\n        <article class="order-card" data-order-id="${escapeHtml(o.orderId)}">\n          <div class="order-card-header">\n            <div>\n              <strong>${escapeHtml(o.orderId)}</strong>\n              <span class="status-badge ${statusClass(o.status)}">${escapeHtml(o.status)}</span>\n            </div>\n            ${inRoom?"":`<label class="sr-only" for="status-${escapeHtml(o.orderId)}">Update status for order ${escapeHtml(o.orderId)}</label>\n            <select id="status-${escapeHtml(o.orderId)}" class="order-status-select" style="width:auto; min-height:36px;">${options}</select>`}\n          </div>\n          ${roomLink(o)}\n          ${docsHtml(o)}\n          <dl>\n            <dt>Customer</dt><dd>${escapeHtml(o.customerName)}</dd>\n            <dt>Phone</dt><dd>${escapeHtml(o.customerPhone)}</dd>\n            ${o.deliveryAddress?`<dt>Address</dt><dd>${escapeHtml(o.deliveryAddress)}</dd>`:""}\n            ${o.deliveryMethod?`<dt>Delivery</dt><dd>${escapeHtml(DELIVERY_ICON_LABELS[o.deliveryMethod]||o.deliveryMethod)}${o.deliveryCost!=null?" — "+(Number(o.deliveryCost)===0?"Free":formatMoney(o.deliveryCost)):""}</dd>`:""}\n            <dt>Payment</dt><dd>${o.paymentMethod?escapeHtml(o.paymentMethod):"Not yet specified"}</dd>\n            <dt>Items</dt><dd>${escapeHtml(o.itemsSummary)}</dd>\n            <dt>Total</dt><dd>${formatMoney(o.total)}</dd>\n            <dt>Placed</dt><dd>${escapeHtml(new Date(o.createdAt).toLocaleString())}</dd>\n            ${o.notes?`<dt>Notes</dt><dd>${escapeHtml(o.notes)}</dd>`:""}\n          </dl>\n        </article>\n      `}).join("")}function docsHtml(o){const docs=o.documents||[];const inv=docs.find(d=>d.kind==="invoice");const link=d=>`<a class="btn btn-small" href="${escapeHtml(d.link||"../invoice.html?d="+d.token)}" target="_blank" rel="noopener">${d.kind==="invoice"?"Invoice":"Receipt"} ${escapeHtml(d.number)}</a>`;const parts=[];if(o.invoiceRequested&&!inv)parts.push('<span class="order-invoice-flag">Buyer asked for an invoice</span>');if(o.invoiceRequested&&o.status!=="Cancelled")parts.push(`<button type="button" class="btn btn-small btn-primary" data-send-invoice="${escapeHtml(o.orderId)}">${inv?"Send invoice again":"Send invoice"}</button>`);docs.forEach(d=>parts.push(link(d)));return parts.length?`<div class="order-docs">${parts.join("")}</div>`:""}async function onSendInvoice(e){const btn=e.target.closest("[data-send-invoice]");if(!btn)return;const orderId=btn.dataset.sendInvoice;btn.disabled=true;btn.textContent="Sending…";const res=await Api.post("sendInvoice",{token:Auth.getToken(),orderId:orderId});if(!res.ok){alert(res.error||"Could not send the invoice.");btn.disabled=false;btn.textContent="Send invoice";return}const order=ownerOrders.find(o=>o.orderId===orderId);if(order)order.documents=(order.documents||[]).filter(d=>d.docId!==res.document.docId).concat([res.document]);render();alert(res.emailed?`Invoice ${res.document.number} sent to the buyer.`:`Invoice ${res.document.number} is ready, but the buyer has no email - share its link with them.`)}async function onStatusChange(e){if(!e.target.classList.contains("order-status-select"))return;const card=e.target.closest(".order-card");const orderId=card.dataset.orderId;const status=e.target.value;const res=await Api.post("updateOrderStatus",{token:Auth.getToken(),orderId:orderId,status:status});if(!res.ok){alert(res.error||"Could not update this order.");await loadOrders();return}const order=ownerOrders.find(o=>o.orderId===orderId);if(order)order.status=status;render();if(status==="Paid"||status==="Fulfilled")loadOrders()}